declare(strict_types=1);putenv('DB_NAME=geo_case_test');require __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/case_workflow.php';$n=0;function flow_ok($v,$m){global$n;if(!$v)throw new RuntimeException("FAIL: $m");$n++;echo"PASS: $m\n";}$before=(int)$conn->query('SELECT COUNT(*) FROM ip_families')->fetch_row()[0];$conn->begin_transaction();try{$admin=(int)$conn->query("SELECT id FROM users WHERE username='admin_test'")->fetch_row()[0];$aff=(int)$conn->query("SELECT id FROM ip_affiliations WHERE code='yapayao'")->fetch_row()[0];$type=(int)$conn->query("SELECT id FROM case_types WHERE code='land_dispute'")->fetch_row()[0];$property=(int)$conn->query("SELECT id FROM property_types WHERE code='land'")->fetch_row()[0];$parcel=(int)$conn->query('SELECT id FROM ip_land_parcels ORDER BY id LIMIT 1')->fetch_row()[0];
$conn->query("INSERT INTO ip_families(family_reference,affiliation_id,owning_tribe,barangay,created_by)VALUES('FLOW-FAM-001',$aff,'Test Tribe','Workflow Barangay',$admin)");$family=(int)$conn->insert_id;$conn->query("INSERT INTO ip_family_members(family_id,member_role,last_name,first_name)VALUES($family,'head','Fictional','Head'),($family,'spouse','Fictional','Spouse')");$head=(int)$conn->query("SELECT id FROM ip_family_members WHERE family_id=$family AND member_role='head'")->fetch_row()[0];flow_ok((int)$conn->query("SELECT COUNT(*) FROM ip_family_members WHERE family_id=$family")->fetch_row()[0]===2,'family with head and optional spouse created');
