$stmt=$conn->prepare("INSERT INTO tax_declarations(td_number,owning_tribe,owner_name,property_type_id,tax_status,parcel_id,owner_family_id,created_by)VALUES('FLOW-TD-001','Test Tribe','Printed Fictional Owner',?,'taxable',?,?,?)");$stmt->bind_param('iiii',$property,$parcel,$family,$admin);$stmt->execute();$tax=(int)$conn->insert_id;$conn->query("INSERT INTO tax_declaration_assessments(tax_declaration_id,classification,area_sqm,market_value,actual_use,assessment_level_percent,assessed_value)VALUES($tax,'Agricultural',100.2500,50000.00,'Agricultural',20.00,10000.00)");$conn->query("INSERT INTO case_tax_declarations(case_id,tax_declaration_id,created_by)VALUES($case,$tax,$admin)");flow_ok((int)$conn->query("SELECT parcel_id FROM tax_declarations WHERE id=$tax")->fetch_row()[0]===$parcel,'Tax Declaration linked to existing parcel');flow_ok((int)$conn->query("SELECT owner_family_id FROM tax_declarations WHERE id=$tax")->fetch_row()[0]===$family,'Tax Declaration linked to family explicitly');flow_ok((int)$conn->query("SELECT COUNT(*) FROM case_tax_declarations WHERE case_id=$case AND tax_declaration_id=$tax")->fetch_row()[0]===1,'case and Tax Declaration linked');flow_ok((int)$conn->query("SELECT COUNT(*) FROM tax_declaration_assessments WHERE tax_declaration_id=$tax")->fetch_row()[0]===1,'assessment retained relationally');flow_ok((int)$conn->query("SELECT COUNT(*) FROM ip_land_parcels WHERE id=$parcel AND (boundary_geojson IS NOT NULL OR (latitude IS NOT NULL AND longitude IS NOT NULL))")->fetch_row()[0]>=0,'parcel remains geometry authority');$conn->query("INSERT INTO audit_logs(user_id,username,role,action,module,record_id,description,ip_address)VALUES($admin,'admin_test','admin','CREATE_FAMILY','ip_families',$family,'Created anonymized cross-phase family','test'),($admin,'admin_test','admin','CREATE_CASE','case_applications',$case,'Created anonymized cross-phase case','test'),($admin,'admin_test','admin','CREATE_TAX_DECLARATION','tax_declarations',$tax,'Created anonymized cross-phase declaration and relationship categories','test')");flow_ok((int)$conn->query("SELECT COUNT(*) FROM audit_logs WHERE record_id IN($family,$case,$tax) AND ip_address='test'")->fetch_row()[0]===3,'cross-module audit events recorded without source PII');flow_ok((int)$conn->query("SELECT COUNT(*) FROM ip_families WHERE id=$family AND owning_tribe='Other Tribe'")->fetch_row()[0]===0,'cross-tribe family predicate denies access');flow_ok((int)$conn->query("SELECT COUNT(*) FROM tax_declarations WHERE id=$tax AND owning_tribe='Other Tribe'")->fetch_row()[0]===0,'cross-tribe declaration predicate denies access');flow_ok((int)$conn->query("SELECT COUNT(*) FROM case_applications WHERE id=$case AND applicant_ip_group='Other Tribe'")->fetch_row()[0]===0,'cross-tribe case predicate denies access');
}finally{$conn->rollback();}flow_ok((int)$conn->query('SELECT COUNT(*) FROM ip_families')->fetch_row()[0]===$before,'complete workflow rolls back cleanly');flow_ok((int)$conn->query("SELECT COUNT(*) FROM tax_declarations WHERE td_number='FLOW-TD-001'")->fetch_row()[0]===0,'no workflow fixture persists');echo"Cross-phase workflow assertions passed: $n\n";
